import type { BodyReferenceImage } from "@/modules/targets/reference-images";
import manifest from "./assets.json";

/**
 * Lunar visualisation assets and their provenance (generated by
 * scripts/fetch-lunar-data.mjs). Kinds: observation-mosaic (spacecraft
 * imagery), elevation-model (measured topography).
 */
export type LunarAssetKind = "observation-mosaic" | "elevation-model";

export interface TerrainWindow {
  centreLatDeg: number;
  centreLonDeg: number;
  sideKm: number;
  samples: number;
  kmPerSample: number;
}

export interface LunarAsset {
  src: string;
  kind: LunarAssetKind;
  source: keyof typeof manifest.sources;
  sourceFile: string;
  processing: string;
  notes: string[];
  retrievedAt: string;
  widthPx?: number;
  heightPx?: number;
  minM?: number;
  maxM?: number;
  featureId?: string;
  window?: TerrainWindow;
}

export const LUNAR_ASSETS = manifest.assets as Record<string, LunarAsset>;
export const LUNAR_ASSET_SOURCES = manifest.sources;

export function terrainAssets(featureId: string): { dem: LunarAsset; albedo: LunarAsset } | undefined {
  const dem = LUNAR_ASSETS[`terrain-${featureId}-dem`];
  const albedo = LUNAR_ASSETS[`terrain-${featureId}-albedo`];
  return dem && albedo ? { dem, albedo } : undefined;
}

/** Albedo map to use for a needed resolution (pixels across 360° of longitude). */
export function albedoFor(widthPx: number): LunarAsset {
  return widthPx > 2048 ? LUNAR_ASSETS["albedo-4k"] : LUNAR_ASSETS["albedo-2k"];
}

/** Provenance of the projected Moon disc, in the shape the view's credit line expects. */
export function moonDiscMeta(map: LunarAsset, sizePx: number): BodyReferenceImage {
  const s = LUNAR_ASSET_SOURCES[map.source];
  return {
    targetId: "moon",
    kind: "body",
    src: `${map.src}#disc`,
    widthPx: sizePx,
    heightPx: sizePx,
    source: {
      name: s.name,
      pageUrl: s.pageUrl,
      credit: s.credit,
      license: s.license,
      description:
        "Lunar Reconnaissance Orbiter Wide Angle Camera global mosaic, projected for tonight's libration and turned to the Moon's axis angle as seen from your site.",
      retrievedAt: map.retrievedAt,
    },
    processing: `${map.processing} Orthographically projected for the computed libration (Meeus ch. 53) and converted to grey.`,
    notes: [
      ...map.notes,
      "Positions of features in this disc are calculated for the observation time and site, so labels line up with what you would see.",
      "The terminator is drawn with a simplified, illustrative shading model.",
    ],
  };
}
